package com.eventdrivencommerce.inventory.infrastructure.outbox;
import com.eventdrivencommerce.inventory.application.port.out.InventoryEventOutbox;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.databind.node.ObjectNode;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
@Component class JpaInventoryEventOutbox implements InventoryEventOutbox {
 private final SpringDataOutboxRepository repository;private final ObjectMapper mapper;JpaInventoryEventOutbox(SpringDataOutboxRepository repository,ObjectMapper mapper){this.repository=repository;this.mapper=mapper;}
 public void reserved(UUID orderId,List<Item> items,UUID correlation,UUID causation,Instant now){ObjectNode p=mapper.createObjectNode();p.put("reservationId",UUID.nameUUIDFromBytes(("inventory:"+orderId).getBytes(StandardCharsets.UTF_8)).toString()).put("orderId",orderId.toString()).put("reservedAt",now.toString()).put("expiresAt",now.plus(Duration.ofMinutes(30)).toString());p.set("items",mapper.valueToTree(items));append("InventoryReservedV1",orderId,correlation,causation,now,p);}
 public void reservationFailed(UUID orderId,List<Failure> failures,UUID correlation,UUID causation,Instant now){ObjectNode p=mapper.createObjectNode();p.put("orderId",orderId.toString()).put("failedAt",now.toString());p.set("failures",mapper.valueToTree(failures));append("InventoryReservationFailedV1",orderId,correlation,causation,now,p);}
 private void append(String type,UUID aggregate,UUID correlation,UUID causation,Instant now,ObjectNode payload){UUID id=UUID.randomUUID();ObjectNode envelope=mapper.createObjectNode();envelope.put("eventId",id.toString()).put("eventType",type).put("eventVersion",1).put("aggregateId",aggregate.toString()).put("correlationId",correlation.toString()).put("causationId",causation.toString()).put("occurredAt",now.toString()).set("payload",payload);repository.save(OutboxJpaEntity.pending(id,aggregate,type,correlation,causation,now,envelope));}
}
